import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Habitacion } from '../../habitaciones/entities/habitacion.entity';
import { Enfermero } from '../../enfermeros/entities/enfermero.entity';

@Injectable()
export class AsignarEnfermeroRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Habitacion) private readonly habitaciones: Repository<Habitacion>,
    @InjectRepository(Enfermero) private readonly enfermeros: Repository<Enfermero>
  ) {}

  buscarHabitacionRepository(habitacionId: number) {
    return this.habitaciones.findOneBy({ id: habitacionId });
  }

  buscarEnfermeroRepository(enfermeroId: number) {
    return this.enfermeros.findOneBy({ id: enfermeroId });
  }

  async asignarEnfermeroRepository(habitacionId: number, enfermeroId: number, rol: string) {
    const asignacion = { habitacionId, enfermeroId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarEnfermeroRepository } from './repository';

@Injectable()
export class AsignarEnfermeroService {
  constructor(private readonly repository: AsignarEnfermeroRepository) {}

  async asignarEnfermeroService(habitacionId: number, enfermeroId: number, rol: string) {
    const habitacion = await this.repository.buscarHabitacionRepository(habitacionId);
    const enfermero = await this.repository.buscarEnfermeroRepository(enfermeroId);
    if (!habitacion || !enfermero) {
      throw new NotFoundException('No existe la habitacion o el enfermero');
    }

    try {
      return await this.repository.asignarEnfermeroRepository(habitacionId, enfermeroId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El enfermero ya está asignado a esa habitacion');
      }
      throw error;
    }
  }
}

